/**
 * Object storage.
 *
 * Three drivers behind one interface. `s3` speaks to any S3-compatible
 * service; `blob` stores in Vercel Blob; `local` writes under a directory and
 * exists so the repository runs with no cloud account and no Docker.
 *
 * Binaries never go in the relational database (§9). What Postgres stores is
 * the `storageKey` plus the identity and provenance of the file — the part that
 * has to be queryable, and the part object storage cannot do.
 *
 * Keys are generated by `buildStorageKey`, never derived from an uploaded
 * filename. A key built from user input is a path-traversal bug waiting to
 * happen, and an S3 key containing `../` is a genuinely confusing thing to
 * debug later.
 */
import { createReadStream, createWriteStream } from "node:fs";
import { mkdir, rename, rm, stat, unlink } from "node:fs/promises";
import { dirname, join, normalize, resolve, sep } from "node:path";
import { Readable } from "node:stream";
import { pipeline } from "node:stream/promises";
import {
  DeleteObjectCommand,
  GetObjectCommand,
  HeadObjectCommand,
  PutObjectCommand,
  S3Client,
} from "@aws-sdk/client-s3";
import { getSignedUrl } from "@aws-sdk/s3-request-presigner";
import { del as blobDel, get as blobGet, head as blobHead, put as blobPut } from "@vercel/blob";
import { AppError, ErrorCode, type Logger, uuidv7 } from "@uxd/shared";

export type StorageDriverName = "local" | "s3" | "blob";

export interface PutObjectInput {
  readonly key: string;
  readonly body: Uint8Array | Readable;
  readonly contentType: string;
  readonly contentLength?: number;
  /**
   * `Content-Disposition`. Defaults to `attachment` for anything that a
   * browser would otherwise execute in our origin — see `dispositionFor`.
   */
  readonly contentDisposition?: string;
  readonly cacheControl?: string;
  readonly metadata?: Record<string, string>;
}

export interface StorageObjectInfo {
  readonly key: string;
  readonly byteSize: number;
  readonly contentType: string | null;
  readonly lastModified: Date | null;
}

export interface StorageDriver {
  readonly name: StorageDriverName;
  readonly bucket: string | null;
  put(input: PutObjectInput): Promise<{ key: string; byteSize: number }>;
  get(key: string): Promise<Readable>;
  head(key: string): Promise<StorageObjectInfo | null>;
  delete(key: string): Promise<void>;
  /**
   * A URL a browser can load the object from.
   *
   * For `s3` with a public base URL this is a plain CDN URL; otherwise it is a
   * presigned URL with a short expiry. For `local` it is a path served by the
   * CMS's own media route, which is development-only.
   */
  url(key: string, options?: { expiresInSeconds?: number; download?: boolean }): Promise<string>;
  /** Whether `url()` returns something that expires. */
  readonly urlsExpire: boolean;
}

/**
 * Content types a browser must never be allowed to render in our origin.
 *
 * An SVG is a document that can contain script; an HTML snapshot obviously can.
 * Serving either inline from the same origin as the CMS would be a stored-XSS
 * vector, so they are always sent as downloads (§9 "do not allow arbitrary
 * uploaded files to be executed").
 */
const FORCE_DOWNLOAD_TYPES = new Set([
  "image/svg+xml",
  "text/html",
  "application/xhtml+xml",
  "application/xml",
  "text/xml",
  "application/pdf",
]);

export function dispositionFor(contentType: string, filename?: string | null): string {
  const safeName = (filename ?? "file").replace(/[^\w.\-]/g, "_").slice(0, 120);
  return FORCE_DOWNLOAD_TYPES.has(contentType)
    ? `attachment; filename="${safeName}"`
    : `inline; filename="${safeName}"`;
}

/**
 * Build a storage key.
 *
 * Shape: `media/<yyyy>/<mm>/<uuid>[-<variant>].<ext>`
 *
 * Date-prefixed so a bucket listing is browsable and a lifecycle rule can
 * target old material. The UUID makes the key unique and unguessable, and it
 * carries no user-supplied text at all.
 */
export function buildStorageKey(input: {
  readonly extension: string;
  readonly variant?: string;
  readonly at?: Date;
  readonly id?: string;
  readonly prefix?: string;
}): string {
  const at = input.at ?? new Date();
  const year = at.getUTCFullYear();
  const month = String(at.getUTCMonth() + 1).padStart(2, "0");
  const id = input.id ?? uuidv7();
  const ext = input.extension.replace(/[^a-z0-9]/gi, "").toLowerCase() || "bin";
  const variant = input.variant ? `-${input.variant.replace(/[^a-z0-9-]/gi, "")}` : "";
  const prefix = (input.prefix ?? "media").replace(/[^a-z0-9/-]/gi, "");
  return `${prefix}/${year}/${month}/${id}${variant}.${ext}`;
}

/** Reject any key that is not the shape we generate. Defence in depth. */
const SAFE_KEY = /^[a-z0-9][a-z0-9/_.-]{0,255}$/i;

export function assertSafeKey(key: string): void {
  if (!SAFE_KEY.test(key) || key.includes("..") || key.includes("//") || key.startsWith("/")) {
    throw new AppError(ErrorCode.BAD_REQUEST, "Invalid storage key", {
      detail: `rejected key: ${key.slice(0, 120)}`,
    });
  }
}

// --- Local driver ---------------------------------------------------------

export interface LocalDriverConfig {
  readonly root: string;
  /** Base URL of the CMS route that serves these files. */
  readonly publicBaseUrl: string;
  readonly logger?: Logger;
}

/**
 * Filesystem driver, for local development only.
 *
 * `loadEnv` refuses to start a production CMS with `STORAGE_DRIVER=local`,
 * because this has none of the durability, access control or CDN behaviour a
 * real deployment needs.
 */
export function createLocalDriver(config: LocalDriverConfig): StorageDriver {
  const root = resolve(config.root);

  /**
   * Resolve a key to an absolute path, refusing anything that escapes `root`.
   *
   * `assertSafeKey` already rejects traversal patterns; this is the second,
   * independent check — resolve the path and confirm it is still inside the
   * root. Two different mechanisms, because a path-traversal bug here writes
   * attacker-chosen bytes to an attacker-chosen location.
   */
  const pathFor = (key: string): string => {
    assertSafeKey(key);
    const full = resolve(join(root, normalize(key)));
    if (full !== root && !full.startsWith(root + sep)) {
      throw new AppError(ErrorCode.BAD_REQUEST, "Invalid storage key", {
        detail: "resolved path escaped the storage root",
      });
    }
    return full;
  };

  return {
    name: "local",
    bucket: null,
    urlsExpire: false,

    async put(input) {
      const path = pathFor(input.key);
      await mkdir(dirname(path), { recursive: true });
      // Write to a temporary name and rename into place, so a crash mid-write
      // cannot leave a truncated file that looks complete.
      const tmp = `${path}.${uuidv7()}.part`;
      try {
        if (input.body instanceof Readable) {
          await pipeline(input.body, createWriteStream(tmp));
        } else {
          await pipeline(Readable.from(Buffer.from(input.body)), createWriteStream(tmp));
        }
        await rename(tmp, path);
        const info = await stat(path);
        return { key: input.key, byteSize: info.size };
      } catch (error) {
        await rm(tmp, { force: true }).catch(() => {});
        throw new AppError(ErrorCode.STORAGE_FAILED, "Could not save the file", {
          detail: error instanceof Error ? error.message : "write failed",
          cause: error,
        });
      }
    },

    async get(key) {
      const path = pathFor(key);
      try {
        await stat(path);
      } catch {
        throw new AppError(ErrorCode.NOT_FOUND, "File not found", { detail: key });
      }
      return createReadStream(path);
    },

    async head(key) {
      try {
        const info = await stat(pathFor(key));
        return { key, byteSize: info.size, contentType: null, lastModified: info.mtime };
      } catch {
        return null;
      }
    },

    async delete(key) {
      try {
        await unlink(pathFor(key));
      } catch (error) {
        // Already gone is success.
        if ((error as { code?: string }).code !== "ENOENT") throw error;
      }
    },

    async url(key, options) {
      assertSafeKey(key);
      const base = config.publicBaseUrl.replace(/\/$/, "");
      const query = options?.download ? "?download=1" : "";
      return `${base}/${key}${query}`;
    },
  };
}

// --- S3 driver ------------------------------------------------------------

export interface S3DriverConfig {
  readonly bucket: string;
  readonly region: string;
  readonly endpoint?: string;
  readonly accessKeyId: string;
  readonly secretAccessKey: string;
  readonly forcePathStyle?: boolean;
  /** CDN or public bucket base URL. When absent, URLs are presigned. */
  readonly publicBaseUrl?: string;
  readonly logger?: Logger;
}

export function createS3Driver(config: S3DriverConfig): StorageDriver {
  const client = new S3Client({
    region: config.region,
    ...(config.endpoint ? { endpoint: config.endpoint } : {}),
    forcePathStyle: config.forcePathStyle ?? false,
    credentials: {
      accessKeyId: config.accessKeyId,
      secretAccessKey: config.secretAccessKey,
    },
    maxAttempts: 3,
  });

  return {
    name: "s3",
    bucket: config.bucket,
    urlsExpire: !config.publicBaseUrl,

    async put(input) {
      assertSafeKey(input.key);
      try {
        await client.send(
          new PutObjectCommand({
            Bucket: config.bucket,
            Key: input.key,
            Body: input.body,
            ContentType: input.contentType,
            ContentLength: input.contentLength,
            ContentDisposition: input.contentDisposition ?? dispositionFor(input.contentType),
            // Derivatives and originals are immutable — a new version gets a
            // new key — so they can be cached indefinitely.
            CacheControl: input.cacheControl ?? "public, max-age=31536000, immutable",
            Metadata: input.metadata,
          }),
        );
        return { key: input.key, byteSize: input.contentLength ?? 0 };
      } catch (error) {
        throw new AppError(ErrorCode.STORAGE_FAILED, "Could not save the file to object storage", {
          detail: error instanceof Error ? error.message : "put failed",
          cause: error,
        });
      }
    },

    async get(key) {
      assertSafeKey(key);
      const result = await client.send(
        new GetObjectCommand({ Bucket: config.bucket, Key: key }),
      );
      if (!result.Body) throw new AppError(ErrorCode.NOT_FOUND, "File not found", { detail: key });
      return result.Body as Readable;
    },

    async head(key) {
      assertSafeKey(key);
      try {
        const result = await client.send(
          new HeadObjectCommand({ Bucket: config.bucket, Key: key }),
        );
        return {
          key,
          byteSize: result.ContentLength ?? 0,
          contentType: result.ContentType ?? null,
          lastModified: result.LastModified ?? null,
        };
      } catch {
        return null;
      }
    },

    async delete(key) {
      assertSafeKey(key);
      await client.send(new DeleteObjectCommand({ Bucket: config.bucket, Key: key }));
    },

    async url(key, options) {
      assertSafeKey(key);
      if (config.publicBaseUrl) {
        return `${config.publicBaseUrl.replace(/\/$/, "")}/${key}`;
      }
      return getSignedUrl(
        client,
        new GetObjectCommand({
          Bucket: config.bucket,
          Key: key,
          ...(options?.download ? { ResponseContentDisposition: "attachment" } : {}),
        }),
        { expiresIn: options?.expiresInSeconds ?? 3600 },
      );
    },
  };
}

// --- Vercel Blob driver ---------------------------------------------------

export interface BlobDriverConfig {
  /** The store's read-write token (Vercel sets `BLOB_READ_WRITE_TOKEN`). */
  readonly token: string;
  /** `private` unless the store was created public. */
  readonly access: "public" | "private";
  /** Base URL of the CMS route that serves these files. */
  readonly publicBaseUrl: string;
  readonly logger?: Logger;
}

/**
 * Vercel Blob.
 *
 * Files are stored under their own key, with no random suffix, so a key maps
 * to exactly one blob. They are never handed to browsers by their Blob URL:
 * like `local`, `url()` points at the CMS's own media routes, which stream the
 * bytes from Blob. That keeps the rule that a capture is private until it is
 * published — the CMS route checks the session, the public route checks that
 * the record is published — whether the store itself is public or private.
 */
export function createBlobDriver(config: BlobDriverConfig): StorageDriver {
  const auth = { token: config.token };

  return {
    name: "blob",
    bucket: null,
    urlsExpire: false,

    async put(input) {
      assertSafeKey(input.key);
      try {
        const body = input.body instanceof Readable ? input.body : Buffer.from(input.body);
        await blobPut(input.key, body, {
          ...auth,
          access: config.access,
          contentType: input.contentType,
          addRandomSuffix: false,
          allowOverwrite: true,
          // Originals and derivatives are immutable: a new version gets a new key.
          cacheControlMaxAge: 31536000,
        });
        const byteSize = input.body instanceof Readable ? (input.contentLength ?? 0) : input.body.byteLength;
        return { key: input.key, byteSize };
      } catch (error) {
        throw new AppError(ErrorCode.STORAGE_FAILED, "Could not save the file to Vercel Blob", {
          detail: error instanceof Error ? error.message : "put failed",
          cause: error,
        });
      }
    },

    async get(key) {
      assertSafeKey(key);
      const result = await blobGet(key, { ...auth, access: config.access });
      if (!result || result.statusCode !== 200 || !result.stream) {
        throw new AppError(ErrorCode.NOT_FOUND, "File not found", { detail: key });
      }
      return Readable.fromWeb(result.stream as import("node:stream/web").ReadableStream<Uint8Array>);
    },

    async head(key) {
      assertSafeKey(key);
      try {
        const info = await blobHead(key, auth);
        return { key, byteSize: info.size, contentType: info.contentType ?? null, lastModified: info.uploadedAt ?? null };
      } catch {
        return null;
      }
    },

    async delete(key) {
      assertSafeKey(key);
      try {
        await blobDel(key, auth);
      } catch (error) {
        // Already gone is success.
        if ((error as { name?: string }).name !== "BlobNotFoundError") throw error;
      }
    },

    async url(key, options) {
      assertSafeKey(key);
      const base = config.publicBaseUrl.replace(/\/$/, "");
      const query = options?.download ? "?download=1" : "";
      return `${base}/${key}${query}`;
    },
  };
}

// --- Factory --------------------------------------------------------------

export interface StorageConfig {
  readonly driver: StorageDriverName;
  readonly localRoot: string;
  readonly localPublicBaseUrl: string;
  readonly s3?: Omit<S3DriverConfig, "logger">;
  readonly blob?: Omit<BlobDriverConfig, "logger" | "publicBaseUrl">;
  readonly logger?: Logger;
}

export function createStorage(config: StorageConfig): StorageDriver {
  if (config.driver === "s3") {
    if (!config.s3) {
      throw new AppError(ErrorCode.INTERNAL, "Storage misconfigured", {
        detail: "STORAGE_DRIVER=s3 but no S3 configuration was supplied",
      });
    }
    return createS3Driver({ ...config.s3, logger: config.logger });
  }
  if (config.driver === "blob") {
    if (!config.blob) {
      throw new AppError(ErrorCode.INTERNAL, "Storage misconfigured", {
        detail: "STORAGE_DRIVER=blob but no BLOB_READ_WRITE_TOKEN was supplied",
      });
    }
    return createBlobDriver({ ...config.blob, publicBaseUrl: config.localPublicBaseUrl, logger: config.logger });
  }
  return createLocalDriver({
    root: config.localRoot,
    publicBaseUrl: config.localPublicBaseUrl,
    logger: config.logger,
  });
}
